<script setup>
import { computed, onBeforeUnmount, onMounted, reactive, ref } from 'vue'
import { useMeta, useQuasar } from 'quasar'
import { api } from 'boot/axios'
import IAChatComponent from 'components/IAChatComponent.vue'
import { notificationGeneratorSeo } from 'src/data/notificationGeneratorSeo'
import { emptyNotification, templateValue, readTemplates, writeTemplate, support, enableNotifications, compactImage, keepLocalImage } from 'src/services/notification-lab'
useMeta(notificationGeneratorSeo)
const $q = useQuasar(), form = reactive(emptyNotification()), templates = ref(readTemplates()), config = ref(null), state = ref(support())
const assistant = ref(false), installDialog = ref(false), review = ref(false), saveDialog = ref(false), slot = ref(0), imageFile = ref(null), mode = ref('upload')
const enabling = ref(false), preparingImage = ref(false), scheduling = ref(false), enabled = ref(false), batch = ref(null), status = ref(''), remaining = ref(0), error = ref(''), screen = ref('ios')
const image = computed(() => form.imageData || (/^https:\/\//.test(form.imageUrl) ? form.imageUrl : ''))
const slots = [{ label: 'Espaço 1', value: 0 }, { label: 'Espaço 2', value: 1 }, { label: 'Espaço 3', value: 2 }]
let subscription, promptEvent, countdown, polling
const requestOptions = extra => ({ timeout: 15000, headers: { 'X-Notification-Lab': '1', ...extra } })
const message = e => e.response?.data?.message || e.message || 'Não foi possível concluir. Tente novamente.'
function notify(e) { error.value = message(e); $q.notify({ type: 'negative', message: error.value }) }
async function loadConfig() { try { config.value = (await api.get('/tools/notification-lab/config', { timeout: 10000 })).data.data } catch { error.value = 'O envio está temporariamente indisponível. Você pode continuar editando e salvando templates.' } }
async function enable() {
  if (!config.value?.publicKey) { error.value = 'A preparação do envio ainda não terminou. Tente novamente em instantes.'; await loadConfig(); return }
  enabling.value = true; error.value = ''
  try { subscription = await enableNotifications(config.value.publicKey); enabled.value = true; $q.notify({ type: 'positive', message: 'Tudo pronto para testar neste dispositivo.' }) }
  catch (e) { notify(e); if (support().installRequired) installDialog.value = true }
  finally { enabling.value = false; state.value = support() }
}
async function selectedImage(file) {
  if (!file) { form.imageData = ''; return }
  preparingImage.value = true
  try { form.imageData = await compactImage(file); form.imageUrl = '' }
  catch (e) { imageFile.value = null; notify(e) }
  finally { preparingImage.value = false }
}
function setImageMode(value) { mode.value = value; imageFile.value = null; form.imageData = ''; form.imageUrl = '' }
function openReview() { try { templateValue(form); error.value = ''; batch.value = null; status.value = ''; review.value = true } catch (e) { notify(e) } }
async function fire() {
  scheduling.value = true; error.value = ''
  try {
    const value = templateValue(form)
    if (!subscription || Notification.permission !== 'granted') { enabled.value = false; throw Error('Ative as notificações neste dispositivo antes de disparar.') }
    const imageRef = await keepLocalImage(value.imageData)
    const response = await api.post('/tools/notification-lab/schedule', { subscription: subscription.toJSON(), title: value.title, body: value.body, count: value.count, delaySeconds: value.delaySeconds, imageRef, imageUrl: value.imageUrl }, requestOptions())
    batch.value = response.data.data; status.value = 'scheduled'; remaining.value = value.delaySeconds
    clearInterval(countdown); clearInterval(polling)
    countdown = setInterval(() => { remaining.value = Math.max(0, remaining.value - 1); if (!remaining.value) clearInterval(countdown) }, 1000)
    const deadline = Date.now() + 30000
    polling = setInterval(async () => {
      if (document.hidden) return
      if (Date.now() > deadline || !batch.value) { clearInterval(polling); return }
      try { const result = (await api.get('/tools/notification-lab/schedule/' + batch.value.id, requestOptions({ 'X-Notification-Lab-Token': batch.value.token }))).data.data; status.value = result.state; if (result.state === 'failed') enabled.value = false; if (['sent', 'failed', 'cancelled'].includes(result.state)) clearInterval(polling) }
      catch { clearInterval(polling) }
    }, 2000)
  } catch (e) { notify(e) } finally { scheduling.value = false }
}
async function cancel() {
  if (!batch.value) return
  try { status.value = (await api.delete('/tools/notification-lab/schedule/' + batch.value.id, requestOptions({ 'X-Notification-Lab-Token': batch.value.token }))).data.data.state; clearInterval(countdown); clearInterval(polling) }
  catch (e) { notify(e) }
}
function save() {
  try {
    const value = templateValue(form), commit = () => { try { templates.value = writeTemplate(slot.value, value); saveDialog.value = false; $q.notify({ type: 'positive', message: 'Template salvo somente neste navegador.' }) } catch (e) { notify(e) } }
    if (templates.value[slot.value]) $q.dialog({ title: 'Substituir este template?', message: 'O conteúdo atual desse espaço será substituído somente neste navegador.', cancel: true, persistent: true }).onOk(commit)
    else commit()
  } catch (e) { notify(e) }
}
function loadTemplate(index) { Object.assign(form, templates.value[index]); imageFile.value = null; mode.value = form.imageUrl ? 'link' : 'upload'; $q.notify({ type: 'positive', message: 'Template carregado para edição.' }) }
function removeTemplate(index) { $q.dialog({ title: 'Remover este template?', message: 'Esta ação afeta apenas este navegador.', cancel: true }).onOk(() => { try { templates.value = writeTemplate(index, null) } catch (e) { notify(e) } }) }
async function install() { if (promptEvent) { await promptEvent.prompt(); await promptEvent.userChoice; promptEvent = null } else installDialog.value = true }
function rememberPrompt(event) { event.preventDefault(); promptEvent = event }
function installed() { promptEvent = null; state.value = support() }
onMounted(() => {
  window.addEventListener('beforeinstallprompt', rememberPrompt); window.addEventListener('appinstalled', installed); loadConfig()
})
onBeforeUnmount(() => { clearInterval(countdown); clearInterval(polling); window.removeEventListener('beforeinstallprompt', rememberPrompt); window.removeEventListener('appinstalled', installed) })
</script>
<template>
<q-layout class="lab"><q-page-container><q-page class="lab-page">
  <div class="lab-orbit lab-orbit--one" aria-hidden="true"/><div class="lab-orbit lab-orbit--two" aria-hidden="true"/>
  <header class="lab-header"><a href="/" aria-label="AitoSoftwares"><img src="/aito-logo-restored.png" width="36" height="36" alt=""/><span><strong>AitoSoftwares</strong><small>NOTIFICATION LAB</small></span></a><q-btn outline rounded no-caps :icon="state.installed?'mdi-check-circle-outline':'mdi-cellphone-arrow-down'" :label="state.installed?'No seu dispositivo':'Adicionar à Tela de Início'" @click="install"/></header>
  <main class="lab-shell">
    <section class="lab-hero"><span class="lab-eyebrow"><i/> UM LABORATÓRIO. SEU DISPOSITIVO.</span><h1>Sua mensagem.<br/><em>Seu próximo alerta.</em></h1><p>Monte uma notificação pessoal, veja a prévia e experimente como ela chega no seu celular. Simples, rápido e com a sua cara.</p><div class="lab-pills"><span><q-icon name="mdi-shield-check-outline"/> Imagens ficam no navegador</span><span><q-icon name="mdi-bookmark-multiple-outline"/> 3 templates locais</span><span><q-icon name="mdi-apple"/><q-icon name="mdi-android"/> Web Push</span></div></section>
    <div class="lab-workspace">
      <section class="lab-builder" aria-label="Criar notificação">
        <header class="lab-section-heading"><span class="lab-step">01</span><div><h2>Crie seu alerta</h2><p>Edite os detalhes. A prévia acompanha você.</p></div><q-btn flat round dense icon="mdi-refresh" aria-label="Restaurar exemplo" @click="Object.assign(form,emptyNotification());imageFile=null;mode='upload'"/></header>
        <q-form @submit.prevent="openReview" class="lab-form">
          <q-input dark outlined v-model="form.title" label="Título da notificação" maxlength="100" counter :rules="[value=>Boolean(value?.trim())||'Informe um título']"/>
          <q-input dark outlined v-model="form.body" type="textarea" autogrow label="Mensagem" maxlength="280" counter/>
          <div class="lab-image-heading"><strong>Imagem <small>opcional</small></strong><q-btn-toggle :model-value="mode" @update:model-value="setImageMode" no-caps rounded unelevated toggle-color="teal-8" :options="[{label:'Do dispositivo',value:'upload'},{label:'Por link',value:'link'}]"/></div>
          <q-file v-if="mode==='upload'" dark outlined v-model="imageFile" @update:model-value="selectedImage" accept="image/png,image/jpeg,image/webp,image/gif,image/avif" label="Escolher imagem · até 5 MB" clearable :loading="preparingImage"><template #prepend><q-icon name="mdi-image-plus-outline"/></template><template #hint>O arquivo é reduzido aqui, sem upload para nosso banco.</template></q-file>
          <q-input v-else dark outlined v-model.trim="form.imageUrl" label="Link HTTPS da imagem" type="url" maxlength="1024" hint="A imagem será carregada pelo seu navegador."/>
          <div v-if="form.imageData" class="lab-local-image"><img :src="form.imageData" alt="Imagem selecionada"/><span>Preparada no seu navegador</span><q-btn flat dense round icon="mdi-close" aria-label="Remover imagem" @click="form.imageData='';imageFile=null"/></div>
          <div class="lab-timing"><q-input dark outlined v-model.number="form.count" type="number" min="1" max="10" label="Quantidade de alertas" :rules="[value=>Number.isInteger(value)&&value>=1&&value<=10||'De 1 a 10 alertas']"/><div><label>Esperar antes de enviar</label><q-btn-toggle v-model="form.delaySeconds" no-caps rounded unelevated toggle-color="teal-7" :options="[{label:'3 s',value:3},{label:'5 s',value:5},{label:'7 s',value:7}]"/></div></div>
          <div class="lab-activation" :class="{'lab-activation--ready':enabled}"><q-icon :name="enabled?'mdi-bell-check-outline':'mdi-bell-ring-outline'" size="28px"/><div><strong>{{enabled?'Notificações prontas':'Permita receber neste dispositivo'}}</strong><p>{{state.installRequired?'No iPhone, abra pelo ícone adicionado à Tela de Início para ativar.':enabled?'O teste será enviado somente para este navegador.':'Você controla a permissão nos ajustes do navegador.'}}</p></div><q-btn v-if="!enabled" no-caps unelevated color="teal-7" label="Ativar" :loading="enabling" :disable="!config?.publicKey" @click="enable"/><q-icon v-else name="mdi-check-circle" color="teal-3" size="24px"/></div>
          <p v-if="error" class="lab-error" role="alert">{{error}}</p>
          <div class="lab-form-actions"><q-btn type="submit" no-caps unelevated color="teal-7" icon="mdi-send-outline" label="Revisar e disparar" :disable="!enabled||preparingImage"/><q-btn outline no-caps icon="mdi-content-save-outline" label="Salvar template" @click="saveDialog=true"/></div>
          <small class="lab-footnote">Teste pessoal, com até 10 alertas por vez e 60 por hora. Seu sistema pode agrupar as notificações. Imagem e aparência variam conforme o dispositivo.</small>
        </q-form>
      </section>
      <aside class="lab-preview-column">
        <div class="lab-preview-heading"><span class="lab-eyebrow">PRÉVIA AO VIVO</span><q-btn-toggle v-model="screen" no-caps flat rounded dense toggle-color="teal-9" :options="[{label:'iOS',value:'ios'},{label:'Android',value:'android'}]"/></div>
        <div class="lab-device" :class="'lab-device--'+screen"><div class="lab-device__camera"/><div class="lab-device__status"><span>9:41</span><span><q-icon name="mdi-signal"/><q-icon name="mdi-wifi"/><q-icon name="mdi-battery-80"/></span></div><div class="lab-device__clock">9:41<small>Hoje é um bom dia para testar.</small></div><article class="lab-notification" aria-live="polite"><header><img :src="image||'/aito-logo-restored.png'" alt="" referrerpolicy="no-referrer" @error="event=>event.target.src='/aito-logo-restored.png'"/><span>NOTIFICATION LAB</span><small>agora</small></header><strong>{{form.title||'Seu título aparece aqui'}}</strong><p>{{form.body||'Sua mensagem aparece aqui.'}}</p><img v-if="image" class="lab-notification__image" :src="image" alt="Prévia da imagem" referrerpolicy="no-referrer" @error="event=>event.target.style.display='none'" :key="image"/></article><small class="lab-device__disclaimer">Prévia ilustrativa. A notificação real segue o visual do seu sistema.</small><div class="lab-device__home"/></div>
        <div class="lab-template-library"><header><span class="lab-step">02</span><div><h2>Seus templates</h2><p>Até três, guardados neste navegador.</p></div></header><div v-for="(item,index) in templates" :key="index" class="lab-template" :class="{'lab-template--empty':!item}"><span class="lab-template__number">0{{index+1}}</span><button v-if="item" type="button" @click="loadTemplate(index)"><strong>{{item.title}}</strong><small>{{item.count}} alerta(s) · {{item.delaySeconds}} segundos</small></button><span v-else>Espaço disponível</span><q-btn v-if="item" flat round dense icon="mdi-trash-can-outline" :aria-label="'Remover template '+(index+1)" @click="removeTemplate(index)"/><q-btn v-else flat round dense icon="mdi-plus" :aria-label="'Salvar no espaço '+(index+1)" @click="slot=index;saveDialog=true"/></div></div>
      </aside>
    </div>
    <section class="lab-help"><h2>Antes do primeiro teste</h2><div><article><q-icon name="mdi-cellphone-arrow-down"/><h3>No iPhone</h3><p>Abra esta página no Safari, toque em Compartilhar e em Adicionar à Tela de Início. Depois, abra pelo novo ícone e ative as notificações.</p></article><article><q-icon name="mdi-timer-sand"/><h3>Prepare e minimize</h3><p>Escolha 3, 5 ou 7 segundos. Após confirmar, minimize ou feche a tela do app. O envio é preparado no servidor, sem depender de a página continuar aberta.</p></article><article><q-icon name="mdi-lock-outline"/><h3>Seus dados, por aqui</h3><p>Templates e imagens enviadas ficam no navegador. O texto e a assinatura de push são usados temporariamente para enviar seu teste, sem criar contatos ou campanhas.</p></article></div><details><summary>Como funciona um simulador de fake notifications no iOS ou Android?</summary><p>Você cria uma notificação de teste do Notification Lab no próprio dispositivo. Ela não é uma mensagem real recebida de outros aplicativos. O sistema mostra a identidade deste webapp e define o ícone, a aparência, o agrupamento e a exibição de imagens.</p></details><details><summary>Por que a imagem ou todos os alertas não apareceram?</summary><p>Alguns sistemas não exibem imagens personalizadas em notificações web. O iOS usa a identidade do app instalado; modos Foco, ajustes de privacidade, agrupamento e permissões também afetam a exibição. Mantenha o dispositivo conectado à internet.</p></details></section>
    <footer class="lab-footer"><img src="/aito-logo-restored.png" width="25" height="25" alt=""/><span>Uma experiência AitoSoftwares.</span><button type="button" @click="assistant=true">Precisa automatizar notificações reais? Fale com a AITO <q-icon name="mdi-arrow-top-right"/></button></footer>
  </main>
  <button class="lab-assistant" type="button" aria-label="Conversar com o assistente AITO" @click="assistant=true"><img src="/ia.gif" width="45" height="45" alt=""/><q-tooltip>Converse com a AITO</q-tooltip></button>
  <q-dialog v-model="assistant"><IAChatComponent @close="assistant=false"/></q-dialog>
  <q-dialog v-model="installDialog"><q-card class="lab-dialog"><q-card-section class="lab-dialog__head"><q-icon name="mdi-cellphone-arrow-down" size="34px"/><q-btn flat round dense icon="mdi-close" aria-label="Fechar instruções" v-close-popup/></q-card-section><q-card-section><h2>Um ícone. Seus próximos testes.</h2><p v-if="state.ios">No Safari, toque em <strong>Compartilhar</strong> <q-icon name="mdi-export-variant"/> e escolha <strong>Adicionar à Tela de Início</strong>. Abra o novo ícone “Notification Lab” para permitir notificações.</p><p v-else>No menu do navegador, escolha <strong>Instalar aplicativo</strong> ou <strong>Adicionar à Tela de Início</strong>. Se a opção não aparecer, você pode usar o gerador em um navegador compatível com notificações.</p><small>O navegador decide quando oferecer a instalação; o site não consegue adicionar o ícone sozinho.</small></q-card-section><q-card-actions align="right"><q-btn no-caps unelevated color="teal-7" label="Entendi" v-close-popup/></q-card-actions></q-card></q-dialog>
  <q-dialog v-model="saveDialog"><q-card class="lab-dialog"><q-card-section class="lab-dialog__head"><div><span class="lab-eyebrow">BIBLIOTECA LOCAL</span><h2>Guarde seu próximo teste.</h2></div><q-btn flat round dense icon="mdi-close" aria-label="Fechar" v-close-popup/></q-card-section><q-card-section><q-select dark outlined v-model="slot" :options="slots" emit-value map-options label="Onde salvar"/><p>O título, a mensagem, a imagem e as opções ficarão apenas neste navegador. Limpar os dados do site também remove os templates.</p></q-card-section><q-card-actions align="right"><q-btn flat no-caps label="Cancelar" v-close-popup/><q-btn unelevated no-caps color="teal-7" label="Salvar neste navegador" @click="save"/></q-card-actions></q-card></q-dialog>
  <q-dialog v-model="review" persistent><q-card class="lab-dialog lab-review"><q-card-section class="lab-dialog__head"><span class="lab-eyebrow">{{batch?'TESTE PREPARADO':'QUASE LÁ'}}</span><q-btn v-if="!scheduling" flat round dense icon="mdi-close" aria-label="Fechar revisão" v-close-popup/></q-card-section><q-card-section v-if="!batch"><q-icon class="lab-review__icon" name="mdi-cellphone-arrow-down" size="48px"/><h2>Confirme. Depois, minimize.</h2><p>Vamos preparar <strong>{{form.count}} alerta(s)</strong>, com uma espera de <strong>{{form.delaySeconds}} segundos</strong>. Assim que confirmar, minimize ou feche esta tela para ver o teste na barra de notificações.</p><div class="lab-review__sample"><strong>{{form.title}}</strong><p>{{form.body}}</p></div></q-card-section><q-card-section v-else><div class="lab-review__count">{{status==='scheduled'?remaining:status==='sent'?'✓':status==='failed'?'!':'·'}}</div><h2>{{status==='sent'?'Encaminhado ao navegador.':status==='failed'?'O envio não foi concluído.':status==='cancelled'?'Teste cancelado.':'Pode minimizar agora.'}}</h2><p>{{status==='failed'?'Ative as notificações novamente e faça um novo teste.':status==='cancelled'?'Você pode voltar e ajustar seu próximo alerta.':'A exibição depende das permissões, da conexão e dos ajustes do dispositivo. O sistema pode agrupar os alertas.'}}</p><q-btn v-if="status==='scheduled'" outline no-caps label="Cancelar este teste" @click="cancel"/></q-card-section><q-card-actions align="right"><q-btn v-if="!batch" flat no-caps label="Voltar" :disable="scheduling" v-close-popup/><q-btn v-if="!batch" unelevated no-caps color="teal-7" icon="mdi-send-outline" label="Confirmar e preparar envio" :loading="scheduling" @click="fire"/><q-btn v-else unelevated no-caps color="teal-7" label="Voltar ao gerador" v-close-popup/></q-card-actions></q-card></q-dialog>
</q-page></q-page-container></q-layout>
</template>
<style scoped>
